return items.map(item => {
  const d = item.json || {};
  const ahora = new Date();
  const ts = Date.now();
  const fecha = ahora.toISOString().slice(0,19).replace('T',' ');

  const nombre = String(d.nombres_apellidos || '').trim();
  const correo = String(d.correo || '').trim().toLowerCase();
  const dni = String(d.dni || '').trim();
  const tipoActividad = String(d.tipo_actividad || '').trim().toLowerCase();
  const nombreActividad = String(d.nombre_actividad || '').trim();
  const periodo = String(d.periodo || '').trim();
  const observaciones = String(d.observaciones || '').trim();

  const completo = Boolean(
    nombre &&
    correo &&
    dni &&
    tipoActividad &&
    nombreActividad &&
    periodo
  );

  return {
    json: {
      id_ejecucion: 'CERT-SIN-' + ts + '-' + Math.random().toString(36).slice(2,7),
      id_incidente: 'INC-CERT-' + ts + '-' + Math.random().toString(36).slice(2,7),

      flujo: '02',
      proceso: 'certificados',
      escenario: 'sin_seguridad',
      bloque: 'sin_seguridad',

      nombres_apellidos: nombre,
      remitente_email: correo,
      dni: dni,
      tipo_actividad: tipoActividad,
      nombre_actividad: nombreActividad,
      periodo: periodo,
      observaciones: observaciones,

      tipo_certificado: 'certificado',
      score_riesgo: null,

      estado_certificado: completo ? 'pendiente' : 'rechazado',
      estado_ejecucion: completo ? 'success' : 'error',

      categoria_sistema: 'sin_clasificacion_seguridad',
      categoria_real: 'pendiente_validacion',
      clasificacion_correcta: false,

      hora_ingreso: fecha,
      hora_procesamiento: fecha
    }
  };
});
